"use client";

import {useEffect,useMemo,useState} from "react";
import {supabase} from "./supabase-client";

type CartItem={id:string|number;name:string;price:number;qty:number;emoji:string;organization_id?:string;image_url?:string;presentation?:string;unit_measure?:string;unit_quantity?:number};
type CatalogProduct={id:string|number;organization_id?:string;name:string;price:number;category:string;description?:string;desc?:string;image_url?:string;unit_measure?:string;unit_quantity?:number;stock?:number;emoji?:string;tag?:string};
type Profile={id:string;email:string;full_name:string|null;platform_role:string};
type Org={id:string;name:string;status:string};
type ProviderApplication={id:string;business_name:string;tax_id:string;contact_name:string;phone:string;city:string;address:string;status:string;created_at:string};
type Order={id:string;order_number:number;organization_name?:string;status:string;payment_method:string;payment_status?:string;total:number;commission_amount:number;customer_data_unlocked?:boolean;customer_name:string;customer_phone?:string;delivery_address?:string;delivery_city?:string;created_at:string};
type TrackingResult={order_number:number;status:string;payment_method:string;total:number;organization_name:string;created_at:string;updated_at:string};

