 useEffect(()=>{let active=true;supabase.from("catalog_products").select("id,organization_id,name,category,description,price,stock,image_url,unit_measure,unit_quantity").eq("is_active",true).order("created_at",{ascending:false}).then(({data})=>{if(active){setCatalog((data||[]) as CatalogProduct[]);setLoading(false)}});return()=>{active=false}},[]);
