 function changeAmount(id:string|number,next:number,stock=0){setAmounts(current=>({...current,[String(id)]:Math.max(1,Math.min(Math.max(stock,1),next))}))}
 function flyToCart(p:CatalogProduct,source:HTMLElement){const target=document.querySelector<HTMLElement>(".cart-button"),image=source.closest("article")?.querySelector<HTMLImageElement>(".product-image img");if(!target)return;const origin=image||source,from=origin.getBoundingClientRect(),to=target.getBoundingClientRect(),fly=document.createElement(image?"img":"span"),size=Math.min(150,Math.max(72,from.width*.55));fly.className="flying-product";if(image)(fly as HTMLImageElement).src=image.src;else fly.textContent="📦";Object.assign(fly.style,{left:`${from.left+from.width/2-size/2}px`,top:`${from.top+from.height/2-size/2}px`,width:`${size}px`,height:`${size}px`,"--fly-x":`${to.left+to.width/2-(from.left+from.width/2)}px`,"--fly-y":`${to.top+to.height/2-(from.top+from.height/2)}px`});document.body.appendChild(fly);target.classList.remove("cart-catch");void target.offsetWidth;target.classList.add("cart-catch");fly.addEventListener("animationend",()=>{fly.remove();setTimeout(()=>target.classList.remove("cart-catch"),250)})}
