 const [category,setCategory]=useState("Todos");const categories=["Todos","Frutas y verduras","Carnes","Huevos y lácteos","Despensa","Bebidas","Aseo"];const visible=category==="Todos"?products:products.filter(p=>p.category===category);
 return <main><section className="hero"><div><span>DEL CAMPO A TU PUERTA</span><h1>Tu mercado local,<br/><em>más fresco que nunca.</em></h1><p>Compra directamente a productores y comercios de tu ciudad. Fácil, rápido y con entrega segura.</p><button onClick={()=>document.getElementById("productos")?.scrollIntoView({behavior:"smooth"})}>Explorar productos →</button></div><div className="hero-art"><b>🥕</b><i>🥑</i><span>🍅</span><small>🚲</small></div></section><section className="benefits"><div>🚚 <span><b>Entrega rápida</b><small>En tu zona</small></span></div><div>🌿 <span><b>Productos frescos</b><small>Calidad local</small></span></div><div>🔒 <span><b>Compra segura</b><small>Pago protegido</small></span></div><div>🤝 <span><b>Apoya lo local</b><small>Comercio justo</small></span></div></section><section id="productos" className="catalog"><header><div><span>RECOMENDADOS PARA TI</span><h2>Lo mejor de tu zona</h2></div>{cart.length>0&&<button onClick={onCheckout}>Ver carrito ({cart.reduce((s,x)=>s+x.qty,0)}) →</button>}</header><div className="product-grid">{products.map(p=><article key={p.id}><div className="product-image"><em>{p.tag}</em><span>{p.emoji}</span><button>♡</button></div><small>{p.desc}</small><h3>{p.name}</h3><div><b>{money(p.price)}</b><button onClick={()=>add(p)}>＋ Agregar</button></div></article>)}</div></section></main>
