const orderTabs=[{id:"pending_confirmation",label:"Por confirmar"},{id:"orders",label:"Pedidos"},{id:"preparing",label:"En preparación"},{id:"dispatched",label:"En despacho"},{id:"out_for_delivery",label:"En ruta"},{id:"delivered",label:"Entregados"},{id:"returned",label:"Devueltos"},{id:"cancelled",label:"Cancelados"}];
function DashboardV2({profile,orgs,providerApplications,providerOrders,adminOrders,wallet,refresh,notify}:{profile:Profile|null;orgs:Org[];providerApplications:ProviderApplication[];providerOrders:Order[];adminOrders:Order[];wallet:number;refresh:()=>void;notify:(x:string)=>void}){
 const admin=profile?.platform_role==="super_admin",org=orgs[0],[tab,setTab]=useState(admin?"admin-orders":"provider-orders"),[orderStatus,setOrderStatus]=useState("pending_confirmation");
 async function move(o:Order,next:string){let note:string|undefined;const coords=next==="delivered"&&navigator.geolocation?await new Promise<{lat?:number,lng?:number}>(r=>navigator.geolocation.getCurrentPosition(p=>r({lat:p.coords.latitude,lng:p.coords.longitude}),()=>r({}))):{};const {error}=await supabase.rpc("set_provider_order_status",{target_order:o.id,next_status:next,status_note:note,delivery_lat:coords.lat,delivery_lng:coords.lng});notify(error?`No se pudo actualizar: ${error.message}`:next==="delivered"?"Pedido entregado y ubicación registrada.":"Estado actualizado.");if(!error)await refresh()}
 async function unlock(o:Order){const {error}=await supabase.rpc("unlock_order_customer_data",{target_order:o.id});notify(error?.message?.includes("insufficient")?`Saldo insuficiente. Necesitas ${money(Number(o.commission_amount))} para desbloquear este pedido.`:error?"No se pudieron desbloquear los datos.":`Datos desbloqueados. Se descontaron ${money(Number(o.commission_amount))}.`);if(!error)void refresh()}
 const orders=admin?adminOrders:providerOrders,filtered=orders.filter(o=>orderStatus==="orders"?["orders","confirmed"].includes(o.status):o.status===orderStatus);
 const nav=[{id:"resumen",label:"Resumen"},...(!admin?[{id:"products",label:"Productos y precios"},{id:"provider-orders",label:"Pedidos"},{id:"history",label:"Historial"},{id:"wallet",label:"Monedas y comisión"}]:[{id:"admin-providers",label:"Proveedores"},{id:"admin-orders",label:"Pedidos"},{id:"admin-cities",label:"Ciudades"},{id:"admin-finance",label:"Comisiones"}])];
 return <main className="dashboard"><aside><div className="dash-brand"><i>go</i><b>market</b><small>{admin?"SUPERADMIN":"PROVEEDOR"}</small></div><div className="business"><span>{(org?.name||"GM").slice(0,2).toUpperCase()}</span><div><b>{org?.name||"GoMarket"}</b><small>{admin?"Administración general":"Panel del proveedor"}</small></div></div><nav>{nav.map(n=><button className={tab===n.id?"active":""} key={n.id} onClick={()=>setTab(n.id)}>{n.label}</button>)}</nav></aside><section className="dash-content"><header><div><span>PANEL DE CONTROL</span><h1>{nav.find(n=>n.id===tab)?.label}</h1></div><div className="dash-user"><span>{(profile?.full_name||profile?.email||"U").slice(0,1)}</span><b>{profile?.full_name||profile?.email}</b></div></header>
 {tab==="resumen"&&<Overview orders={providerOrders} admin={adminOrders} wallet={wallet} isAdmin={admin}/>} {tab==="products"&&<ProductManager org={org} notify={notify}/>} {(tab==="provider-orders"||tab==="admin-orders")&&<><OrderStatusTabs value={orderStatus} setValue={setOrderStatus} orders={orders}/><OrdersTable orders={filtered} move={admin?undefined:move} unlock={admin?undefined:unlock} admin={admin} notify={notify} refresh={refresh}/></>} {tab==="history"&&<OrdersTable orders={orders.filter(o=>["delivered","returned","cancelled"].includes(o.status))} move={move} unlock={unlock} notify={notify} refresh={refresh}/>} {tab==="wallet"&&<Wallet wallet={wallet} recharge={()=>notify("Las recargas reales se conectarán a la pasarela de pagos.")}/>} {tab==="admin-providers"&&<AdminProviders orgs={orgs} applications={providerApplications} notify={notify} refresh={refresh}/>} {tab==="admin-cities"&&<CityManager notify={notify}/>} {tab==="admin-finance"&&<Finance orders={adminOrders}/>}</section></main>
}

function AdminProviders({orgs,applications,notify,refresh}:{orgs:Org[];applications:ProviderApplication[];notify:(x:string)=>void;refresh:()=>void}){
 const pending=applications.filter(a=>a.status==="pending");
 async function review(id:string,decision:"approved"|"rejected"){const {error}=await supabase.rpc("review_provider_application",{target_application:id,decision});notify(error?"No fue posible revisar la solicitud.":decision==="approved"?"Proveedor aprobado y empresa vinculada.":"Solicitud rechazada.");if(!error)void refresh()}
 return <div className="admin-card"><div className="table-head"><div><h2>Solicitudes de proveedores</h2><p>Aprueba la empresa para habilitar su panel, productos y pedidos.</p></div><b>{pending.length} pendientes</b></div>{pending.length?pending.map(a=><div className="provider-row" key={a.id}><span>{a.business_name.slice(0,2).toUpperCase()}</span><div><b>{a.business_name}</b><small>{a.contact_name} · {a.tax_id} · {a.city} · {a.phone}</small></div><em className="status pending">Pendiente</em><button onClick={()=>review(a.id,"rejected")}>Rechazar</button><button className="primary" onClick={()=>review(a.id,"approved")}>Aprobar</button></div>):<div className="table-empty">No hay solicitudes pendientes.</div>}<div className="table-head"><div><h2>Empresas vinculadas</h2><p>Proveedores que ya tienen acceso a GoMarket.</p></div></div>{orgs.map(o=><div className="provider-row" key={o.id}><span>{o.name.slice(0,2).toUpperCase()}</span><div><b>{o.name}</b><small>Empresa vinculada a GoMarket</small></div><em className={`status ${o.status}`}>{o.status}</em></div>)}</div>
}

function OrderStatusTabs({value,setValue,orders}:{value:string;setValue:(x:string)=>void;orders:Order[]}){return <div className="order-tabs">{orderTabs.map(t=><button className={value===t.id?"active":""} onClick={()=>setValue(t.id)} key={t.id}>{t.label}<em>{orders.filter(o=>t.id==="orders"?["orders","confirmed"].includes(o.status):o.status===t.id).length}</em></button>)}</div>}
function ProductManagerLegacy({org,notify}:{org?:Org;notify:(x:string)=>void}){return <div>{org?.name}{String(notify)}</div>}

function ProductManager({org,notify}:{org?:Org;notify:(x:string)=>void}){
 const empty={name:"",category:"Frutas y verduras",price:"",stock:"",description:"",unit_measure:"unidad",unit_quantity:"1",sku:""};
 const [list,setList]=useState<any[]>([]),[open,setOpen]=useState(false),[saving,setSaving]=useState(false),[importing,setImporting]=useState(false),[image,setImage]=useState<File|null>(null),[preview,setPreview]=useState(""),[editingId,setEditingId]=useState<string|null>(null),[f,setF]=useState(empty);
 const load=()=>{if(org)supabase.from("catalog_products").select("*").eq("organization_id",org.id).order("created_at",{ascending:false}).then(({data})=>setList(data||[]))};useEffect(load,[org]);
 const presentation=(p:any)=>p.unit_measure==="unidad"?`${p.unit_quantity||1} unidad${Number(p.unit_quantity||1)>1?"es":""}`:`${p.unit_quantity||1} ${p.unit_measure}${Number(p.unit_quantity||1)>1?"s":""}`;
 async function uploadImage(){if(!image||!org)return "";const ext=image.name.split(".").pop()?.toLowerCase()||"jpg",path=`${org.id}/${crypto.randomUUID()}.${ext}`;const {error}=await supabase.storage.from("product-images").upload(path,image,{upsert:false});if(error)throw error;return supabase.storage.from("product-images").getPublicUrl(path).data.publicUrl}
 async function save(){
  const missing=[] as string[];
  if(!org){notify("Tu cuenta todavía no tiene una empresa vinculada. Completa o espera la aprobación del registro de empresa.");return}
  if(!f.name.trim())missing.push("nombre del producto");
  if(f.price.trim()===""||!Number.isFinite(Number(f.price))||Number(f.price)<=0)missing.push("precio mayor que cero");
  if(f.stock.trim()===""||!Number.isInteger(Number(f.stock))||Number(f.stock)<0)missing.push("inventario (puede ser 0)");
  if(f.unit_quantity.trim()===""||!Number.isFinite(Number(f.unit_quantity))||Number(f.unit_quantity)<=0)missing.push("cantidad por presentación");
  if(missing.length){notify(`Revisa: ${missing.join(", ")}.`);return}
  setSaving(true);try{const uploadedImage=await uploadImage(),payload={...f,name:f.name.trim(),sku:f.sku.trim(),description:f.description.trim(),organization_id:org!.id,price:Number(f.price),stock:Number(f.stock),unit_quantity:Number(f.unit_quantity),...(uploadedImage?{image_url:uploadedImage}:{})};const {data,error}=editingId?await supabase.rpc("update_catalog_product",{target_product:editingId,payload}):await supabase.rpc("save_catalog_product",{payload:{...payload,image_url:uploadedImage}});if(error)throw error;setList(editingId?list.map(p=>p.id===editingId?data:p):[data,...list]);setF(empty);setImage(null);setPreview("");setEditingId(null);setOpen(false);notify(editingId?"Producto actualizado correctamente.":"Producto guardado correctamente.")}catch(e:any){notify(`No pudimos guardar el producto: ${e.message||"revisa los datos"}`)}finally{setSaving(false)}}
 async function importCsv(file:File){
  if(!org)return;setImporting(true);
  try{
   const text=(await file.text()).replace(/^\uFEFF/,""),lines=text.split(/\r?\n/).filter(line=>line.trim()),delimiter=lines[0].includes("\t")?"\t":lines[0].includes(";")?";":",";
   const normalize=(value:string)=>value.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
   const headers=lines[0].split(delimiter).map(normalize),validUnits:Record<string,string>={unidad:"unidad",unidades:"unidad",libra:"libra",libras:"libra",lb:"libra",gramo:"gramo",gramos:"gramo",gr:"gramo",kilogramo:"kilogramo",kilogramos:"kilogramo",kilo:"kilogramo",kilos:"kilogramo",kg:"kilogramo"};
   let ok=0;const failures:string[]=[];
   for(const [index,line] of lines.slice(1).entries()){
    const values=line.split(delimiter).map(x=>x.trim()),row=Object.fromEntries(headers.map((h,i)=>[h,values[i]||""]));
    let unitRaw=normalize(row.unidad||row.unit_measure||"unidad"),quantityRaw=row.cantidad||row.unit_quantity||"1";
    if(!validUnits[unitRaw]&&validUnits[normalize(quantityRaw)]&&Number.isFinite(Number(unitRaw))){const swapped=quantityRaw;quantityRaw=unitRaw;unitRaw=normalize(swapped)}
    const name=row.nombre||row.name,price=Number(row.precio||row.price),stock=Number(row.inventario||row.stock||0),unit=validUnits[unitRaw],quantity=Number(quantityRaw);
    if(!name||!Number.isFinite(price)||price<=0||!Number.isInteger(stock)||stock<0||!unit||!Number.isFinite(quantity)||quantity<=0){failures.push(`fila ${index+2}`);continue}
    const {error}=await supabase.rpc("save_catalog_product",{payload:{organization_id:org.id,name,category:row.categoria||row.category||"Despensa",description:row.descripcion||row.description||"",price,stock,unit_measure:unit,unit_quantity:quantity,sku:row.sku||"",image_url:row.imagen||row.image_url||""}});
    if(error)failures.push(`fila ${index+2}: ${error.message}`);else ok++
   }
   notify(failures.length?`${ok} productos importados. No se pudieron importar ${failures.length} (${failures.slice(0,3).join(", ")}).`:`${ok} productos importados correctamente.`);load()
  }catch(e:any){notify(`No pudimos importar el archivo: ${e.message}`)}finally{setImporting(false)}
 }
 function chooseImage(file?:File){if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){notify("La imagen debe ser JPG, PNG o WEBP y pesar máximo 5 MB.");return}setImage(file);setPreview(URL.createObjectURL(file))}
 function editProduct(p:any){setEditingId(p.id);setF({name:p.name||"",category:p.category||"Frutas y verduras",price:String(p.price??""),stock:String(p.stock??""),description:p.description||"",unit_measure:p.unit_measure||"unidad",unit_quantity:String(p.unit_quantity??1),sku:p.sku||""});setImage(null);setPreview(p.image_url||"");setOpen(true);window.scrollTo({top:0,behavior:"smooth"})}
 useEffect(()=>{const buttons=Array.from(document.querySelectorAll<HTMLButtonElement>(".product-admin-grid article button")),handlers=buttons.map((button,index)=>{const handler=()=>editProduct(list[index]);button.addEventListener("click",handler);return handler});return()=>buttons.forEach((button,index)=>button.removeEventListener("click",handlers[index]))},[list]);
 return <div className="admin-card"><div className="table-head"><div><h2>Productos y precios</h2><p>Administra fotografía, presentación, precio e inventario de tu catálogo.</p></div><div className="catalog-actions"><label className="import-button">{importing?"Importando…":"⇧ Importar CSV"}<input type="file" accept=".csv,text/csv" disabled={importing} onChange={e=>e.target.files?.[0]&&importCsv(e.target.files[0])}/></label><button className="primary" onClick={()=>setOpen(!open)}>＋ Nuevo producto</button></div></div><div className="csv-help"><b>Importación masiva:</b> usa columnas nombre, categoria, precio, inventario, unidad, cantidad, sku, descripcion e imagen.</div>{open&&<div className="product-editor"><label className="image-upload">{preview?<img src={preview} alt="Vista previa"/>:<span>📷<b>Cargar fotografía</b><small>JPG, PNG o WEBP · máximo 5 MB</small></span>}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>chooseImage(e.target.files?.[0])}/></label><div className="product-form form-grid"><label>Nombre del producto *<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>SKU / referencia<input value={f.sku} onChange={e=>setF({...f,sku:e.target.value})}/></label><label>Categoría *<select required value={f.category} onChange={e=>setF({...f,category:e.target.value})}><option>Frutas y verduras</option><option>Carnes</option><option>Huevos y lácteos</option><option>Despensa</option><option>Bebidas</option><option>Aseo y hogar</option></select></label><label>Precio de esta presentación *<input required type="number" min="0.01" step="0.01" value={f.price} onChange={e=>setF({...f,price:e.target.value})}/></label><label>Unidad de medida *<select required value={f.unit_measure} onChange={e=>setF({...f,unit_measure:e.target.value})}><option value="unidad">Unidad</option><option value="libra">Libra</option><option value="gramo">Gramo</option><option value="kilogramo">Kilogramo</option></select></label><label>Cantidad por presentación *<input required type="number" min="0.001" step="0.001" value={f.unit_quantity} onChange={e=>setF({...f,unit_quantity:e.target.value})}/><small>Ej.: 1 kilogramo, 500 gramos o 6 unidades.</small></label><label>Inventario disponible *<input required type="number" min="0" step="1" value={f.stock} onChange={e=>setF({...f,stock:e.target.value})}/><small>Puedes escribir 0 si todavía no tienes existencias.</small></label><label className="full">Descripción<input value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><button type="button" className="primary full" disabled={saving} onClick={save}>{saving?"Guardando…":"Guardar producto"}</button></div></div>}<div className="product-admin-grid">{list.length?list.map(p=><article key={p.id}>{p.image_url?<img className="admin-product-image" src={p.image_url} alt={p.name}/>:<span>📦</span>}<div><b>{p.name}</b><small>{p.category} · {presentation(p)} · inventario: {p.stock}</small></div><strong>{money(Number(p.price))}</strong><button>Editar</button></article>):<div className="table-empty">Aún no has registrado productos.</div>}</div></div>
}
function CityManager({notify}:{notify:(x:string)=>void}){const [cities,setCities]=useState(["Barranquilla","Soledad"]),[city,setCity]=useState("");async function add(){if(!city)return;const {error}=await supabase.from("service_cities").insert({name:city});if(!error)setCities([...cities,city]);setCity("");notify(error?"No fue posible agregar la ciudad.":"Ciudad habilitada para entregas.")}return <div className="admin-card"><div className="table-head"><div><h2>Ciudades de cobertura</h2><p>Define dónde pueden comprar los clientes.</p></div></div><div className="city-add"><input placeholder="Nueva ciudad" value={city} onChange={e=>setCity(e.target.value)}/><button className="primary" onClick={add}>Agregar ciudad</button></div>{cities.map(c=><div className="provider-row" key={c}><span>📍</span><div><b>{c}</b><small>Disponible para pedidos</small></div><em className="status active">Activa</em></div>)}</div>}
